{"task_id": "T31", "code": "def solve(s):
    """Return run-length encoding of a string as list of [char, count].
    Handles non-string or empty inputs gracefully.
    """
    # If s is not a string or is empty, return empty list.
    if not isinstance(s, (str, bytes, bytearray)) or len(s) == 0:
        return []
    # Ensure we treat bytes as characters by decoding if needed.
    if isinstance(s, (bytes, bytearray)):
        try:
            s = s.decode()
        except Exception:
            # fallback to converting each byte to a char
            s = ''.join(chr(b) for b in s)
    result = []
    prev = s[0]
    count = 1
    for ch in s[1:]:
        if ch == prev:
            count += 1
        else:
            result.append([prev, count])
            prev = ch
            count = 1
    result.append([prev, count])
    return result
}"}

