def solve(nums):
    """Return length of longest strictly increasing subsequence using patience sorting (O(n log n))."""
    import bisect
    tails = []
    for x in nums:
        # Find insertion point (first >= x) to keep tails minimal
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

